import { Component } from '@angular/core';


@Component({
  selector: 'app-carrito',
  templateUrl: './carrito.component.html',
  styleUrls: ['./carrito.component.css']
})
export class CarritoComponent {

  constructor(private carritoService: CarritoComponent) {
    // Obtiene la lista de productos en el carrito desde el servicio CarritoComponent
    this.productosEnCarrito = this.carritoService.obtenerProductosEnCarrito();
  }
}
<div class="card">
  <div class="card-body">
    <h5 class="card-title">Carrito de compras<i class="bi bi-cart" style="font-size: 24px; margin: 0 10px;"></i></h5>
    <h6 class="card-subtitle text-muted">Productos en el carrito:</h6>
    <ul>
      <li *ngFor="let producto of productosEnCarrito">
        {{ producto.nombre }} - Precio: ${{ producto.precio }}
      </li>
    </ul>
    <!-- Aquí puedes agregar más productos en el carrito -->
    <a href="#" class="card-link">Ver carrito</a>
  </div>
</div>
